*** tokio/tests/sync_broadcast.rs.orig
--- tokio/tests/sync_broadcast.rs
***************
*** 503,508 ****
--- 503,552 ----
      assert_empty!(rx_resub);
  }

+ #[test]
+ fn resubscribe_closed_try_recv() {
+     for capacity in [1, 4] {
+         for messages in 0..6 {
+             let (tx, rx) = broadcast::channel(capacity);
+             for value in 0..messages {
+                 assert_ok!(tx.send(value));
+             }
+             drop(tx);
+ 
+             let mut rx_resub = rx.resubscribe();
+             assert_closed!(rx_resub.try_recv());
+ 
+             let mut rx_resub = rx_resub.resubscribe();
+             drop(rx);
+             assert_closed!(rx_resub.try_recv());
+         }
+     }
+ }
+ 
+ #[test]
+ fn resubscribe_closed_recv() {
+     for capacity in [1, 4] {
+         for messages in 0..6 {
+             let (tx, rx) = broadcast::channel(capacity);
+             for value in 0..messages {
+                 assert_ok!(tx.send(value));
+             }
+             drop(tx);
+ 
+             let mut rx_resub = rx.resubscribe();
+             drop(rx);
+ 
+             let mut recv = task::spawn(rx_resub.recv());
+             let err = assert_ready_err!(recv.poll());
+             assert!(is_closed(err));
+         }
+     }
+ }
+ 
  #[test]
  fn resubscribe_lagged() {
      let (tx, mut rx) = broadcast::channel(1);
PATCH
