if [ $? -eq 0 ]; then cargo test --offline --quiet --test sync_broadcast --features full resubscribe_closed > /testbed/target/broadcast-regression.log 2>&1; result=$?; tail -45 /testbed/target/broadcast-regression.log; exit "$result"; fi

cd /testbed && patch -p0 <<'PATCH'
--- tokio/src/sync/broadcast.rs
+++ tokio/src/sync/broadcast.rs
@@ -667,7 +667,12 @@

     tail.rx_cnt = tail.rx_cnt.checked_add(1).expect("overflow");

-    let next = tail.pos;
+    let next = if tail.closed {
+        // Start at the close signal rather than the next empty slot.
+        tail.pos.wrapping_sub(1)
+    } else {
+        tail.pos
+    };

     drop(tail);

@@ -897,6 +902,9 @@
     /// **after** it has resubscribed. This will not include elements that are
     /// in the queue of the current receiver. Consider the following example.
     ///
+    /// If the channel is closed, the returned receiver will immediately return
+    /// `RecvError::Closed` from `recv`.
+    ///
     /// # Examples
     ///
     /// ```
PATCH
if [ $? -eq 0 ]; then cargo test --offline --quiet --test sync_broadcast --features full > /testbed/target/broadcast-regression.log 2>&1; result=$?; tail -12 /testbed/target/broadcast-regression.log; exit "$result"; fi

